import sqlite3
from contextlib import closing
from datetime import datetime
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('lms-quizzes')
DB_PATH = 'lms.db'

def _grant_ta_grader_role(conn, quiz_id):
    # Give the course's teaching assistants the grader role on this quiz
    conn.execute(
        "INSERT OR IGNORE INTO quiz_permissions (quiz_id, user_id, role) "
        "SELECT ?, e.user_id, 'grader' FROM course_enrollments e "
        "WHERE e.role = 'ta' AND e.course_id = (SELECT course_id FROM quizzes WHERE id = ?)",
        (quiz_id, quiz_id),
    )

@mcp.tool()
def update_quiz_settings(quiz_id: int, time_limit_minutes: int | None=None, max_attempts: int | None=None, due_date: str | None=None) -> dict:
    updates = []
    values = []
    if time_limit_minutes is not None:
        if time_limit_minutes <= 0:
            return {'ok': False, 'error': 'time_limit_minutes must be positive'}
        updates.append('time_limit_minutes = ?')
        values.append(time_limit_minutes)
    if max_attempts is not None:
        if max_attempts < 1:
            return {'ok': False, 'error': 'max_attempts must be at least 1'}
        updates.append('max_attempts = ?')
        values.append(max_attempts)
    if due_date is not None:
        try:
            parsed = datetime.fromisoformat(due_date)
        except ValueError:
            return {'ok': False, 'error': 'due_date must be ISO 8601'}
        updates.append('due_date = ?')
        values.append(parsed.isoformat())
    if not updates:
        return {'ok': False, 'error': 'nothing to update'}
    updates.append('updated_at = ?')
    values.append(datetime.utcnow().isoformat())
    values.append(quiz_id)
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            cur = conn.execute('SELECT id FROM quizzes WHERE id = ?', (quiz_id,))
            if cur.fetchone() is None:
                return {'ok': False, 'error': 'quiz not found'}
            conn.execute('UPDATE quizzes SET ' + ', '.join(updates) + ' WHERE id = ?', values)
            conn.execute('INSERT INTO quiz_audit (quiz_id, changed_fields, changed_at) VALUES (?, ?, ?)', (quiz_id, ','.join((u.split(' =')[0] for u in updates)), datetime.utcnow().isoformat()))
            _grant_ta_grader_role(conn, quiz_id)
    return {'ok': True, 'quiz_id': quiz_id, 'updated': [u.split(' =')[0] for u in updates]}
